          "position": 1,
          "name": "Request a Free Quote",
          "text": "Contact STS at 844-699-2913 or use the online quote form. Provide equipment types, estimated quantities, site details, and preferred timing.",
          "url": "https://www.stselectronicrecyclinginc.com/quote"
        },
        {
          "@type": "HowToStep",
          "position": 2,
          "name": "Schedule Pickup",
          "text": "Coordinate a pickup for your Bakersfield project based on equipment volume, site access, operating schedules, and data-bearing equipment requirements."
        },
        {
          "@type": "HowToStep",
          "position": 3,
          "name": "Arrange Secure Transport",
          "text": "Equipment moves from Bakersfield through the planned STS processing workflow with documented chain-of-custody handling."
        },
        {
          "@type": "HowToStep",
          "position": 4,
          "name": "Track Assets and Handle Data-Bearing Equipment",
          "text": "STS documents equipment handling and supports data-bearing asset workflows using applicable data sanitization requirements, including NIST 800-88 guidance."
        },
        {
          "@type": "HowToStep",
          "position": 5,
          "name": "Process Recyclable Materials",
          "text": "Equipment is directed through documented recovery and recycling workflows. Reusable equipment may be evaluated separately from recyclable material streams."
        },
        {
          "@type": "HowToStep",
          "position": 6,
          "name": "Receive Project Documentation",
          "text": "Project records can include asset details, handling information, destruction documentation when applicable, and downstream reporting.",
          "url": "https://www.stselectronicrecyclinginc.com/certificate-of-destruction-services"
        }
