      "mainEntity": [
        {
          "@type": "Question",
          "name": "What certifications and standards guide your work?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "STS uses documented processes that reference applicable standards and client requirements, including NIST 800-88 for media sanitization and HIPAA-related privacy considerations. Project documentation can be structured around the equipment, volume, and reporting needs identified during intake. These references help organizations compare vendors, define project requirements, and retain records for internal security or privacy reviews."
          }
        },
        {
          "@type": "Question",
          "name": "What areas do you serve?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "STS serves Bakersfield, Kern County, and organizations throughout the Central Valley. Pickup planning can cover offices, campuses, healthcare environments, industrial sites, and public-sector facilities based on equipment volume and access requirements."
          }
        },
        {
          "@type": "Question",
          "name": "How long does pickup take?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Scheduling depends on equipment volume, site access, and transportation requirements. Many qualifying projects can be arranged during the same week after the scope is confirmed, with timing communicated before collection is finalized."
          }
        },
        {
          "@type": "Question",
          "name": "What happens to equipment after pickup?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Equipment is received, documented, and directed through the appropriate processing workflow. Data-bearing assets can receive designated handling, while reusable components and recyclable materials move through documented recovery channels."
          }
        }
      ]
